def parallel(n, fn, pool=40):
    """Run fn(i) for i in range(n) concurrently. Returns (results, errors)."""
    import concurrent.futures
    errs = []

    def wrap(i):
        try:
            return fn(i)
        except Exception as e:
            errs.append((i, e, traceback.format_exc(limit=4)))
            return None

